const fs = require("node:fs");
const path = require("node:path");

const { withDangerousMod } = require("expo/config-plugins");

// Xcode Cloud only runs ci_scripts beside the workspace, and prebuild wipes ios/.
// The launcher hands over at once: prebuild deletes it while the build is running.
const LAUNCHER = `#!/bin/bash
# Generated by apps/mobile/plugins/withXcodeCloudScripts.cjs: edit the plugin, not this file.
set -euo pipefail
exec /bin/bash "$(cd "$(dirname "\${BASH_SOURCE[0]}")/../../../.." && pwd)/scripts/t4/xcode-cloud/post-clone.sh"
`;

module.exports = function withXcodeCloudScripts(config) {
  return withDangerousMod(config, [
    "ios",
    (nextConfig) => {
      const directory = path.join(nextConfig.modRequest.platformProjectRoot, "ci_scripts");
      fs.mkdirSync(directory, { recursive: true });
      fs.writeFileSync(path.join(directory, "ci_post_clone.sh"), LAUNCHER, { mode: 0o755 });
      return nextConfig;
    },
  ]);
};
